#include "dw3000_deca_regs.h"
#include <string.h>
/* 300 logical records per reporting cycle. Hardware A/B measure the actual link.
 * mode 0 one DATA, mode 1 five DATA copies, mode 2 POLL/DATA with selective retry.
 * Packet overhead remains 30 bytes including MAC, experiment fields and FCS.
 * Data packs exactly 30 bits/record (4 or 38 bytes for aggregation 1 or 10).
 */
volatile struct {uint32_t command,run,count,mode,node,preamble,aggregation,ifs_us,loss_permille,seed,max_attempts,timeout_us;} control;
volatile struct {uint32_t state,run,devid,tx_data,tx_poll,rx_data,rx_poll,unique,first_unique,duplicates,invalid,phy_errors,poll_dropped,data_dropped,late_tx,tx_errors,timeouts,completed,failed,elapsed,batches,period_n,period_min,period_max,period_lo,period_hi;} stats;
uint8_t received[6250],txbuf[80],rxbuf[80];
uint32_t batch_us[1667],batch_failed[1667],period_hist[2048];
static uint64_t rxstamp,last_stamp,period_sum;
static uint32_t last_seq,macseq;
static unsigned rxlen,txlen,have_stamp;
static uint32_t get(const uint8_t *b,unsigned n){uint32_t v=0;for(unsigned i=0;i<4;i++)v|=(uint32_t)b[n+i]<<(8*i);return v;}
static void put(uint8_t *b,unsigned n,uint32_t v){for(unsigned i=0;i<4;i++)b[n+i]=v>>(8*i);}
static uint32_t mix(uint32_t x){x^=x>>16;x*=0x7feb352du;x^=x>>15;x*=0x846ca68bu;return x^(x>>16);}
static int drop(uint32_t seq,uint32_t attempt,unsigned kind){return mix(control.seed^mix(seq)^mix(attempt+0x1234567u)^mix(kind))%1000<control.loss_permille;}
static uint32_t datum(uint32_t record){return mix(control.run^record)&0x3fffffffu;}
static unsigned data_bytes(void){return (control.aggregation*30+7)/8;}
static void payload(uint8_t *b,uint32_t seq){memset(b,0,data_bytes());for(unsigned j=0;j<control.aggregation;j++){uint32_t v=datum(seq*control.aggregation+j);for(unsigned k=0;k<30;k++)if(v&(1u<<k)){unsigned bit=j*30+k;b[bit/8]|=1u<<(bit%8);}}}
static int valid_payload(uint32_t seq){uint8_t expected[38];payload(expected,seq);return !memcmp(expected,rxbuf+28,data_bytes());}
/* Rounded-up nominal PPDU duration; Qorvo DW3000 datasheet tables 18 and frame format. */
static uint32_t airtime(unsigned bytes){uint32_t bits=8*bytes;return ((control.preamble+8)*101763u+21*102564u+(bits+48*((bits+329)/330))*12821u+99999u)/100000u;}
static uint64_t stamp_us(uint64_t stamp,uint32_t us){return (stamp+(uint64_t)us*638976/10)&0xffffffffffULL;}
static void off(void){dwt_forcetrxoff();dwt_writesysstatuslo(DWT_INT_TXFRS_BIT_MASK|DWT_INT_RXFCG_BIT_MASK|SYS_STATUS_ALL_RX_ERR|SYS_STATUS_ALL_RX_TO);}
static void listen(void){off();dwt_setrxtimeout(0);dwt_rxenable(DWT_START_RX_IMMEDIATE);}
static dwt_config_t config={5,DWT_PLEN_128,DWT_PAC8,9,9,1,DWT_BR_6M8,DWT_PHRMODE_STD,DWT_PHRRATE_STD,129,DWT_STS_MODE_OFF,DWT_STS_LEN_64,DWT_PDOA_M0};
static int setup(void){NRF_SPI0->FREQUENCY=0x10000000;output(RESET,0);deca_sleep(2);NRF_P0->PIN_CNF[RESET]=0;deca_sleep(10);if(dwt_probe((struct dwt_probe_s*)&probe))return -1;stats.devid=dwt_readdevid();if(stats.devid!=0xdeca0302)return -2;uint32_t t=ticks();while(!dwt_checkidlerc())if(ticks()-t>100000)return -3;if(dwt_initialise(DWT_READ_OTP_ALL))return -4;config.txPreambLength=control.preamble;config.sfdTO=control.preamble+1;if(dwt_configure(&config))return -5;dwt_txconfig_t power={0x34,0xfdfdfdfd,0};dwt_configuretxrf(&power);dwt_setpanid(0xdeca);dwt_setaddress16(control.node);dwt_configureframefilter(DWT_FF_ENABLE_802_15_4,DWT_FF_DATA_EN);NRF_SPI0->FREQUENCY=0x80000000;return 0;}
static void prepare(unsigned type,uint32_t seq,uint32_t attempt){memset(txbuf,0,sizeof(txbuf));txbuf[0]=0x41;txbuf[1]=0x88;txbuf[2]=macseq++;txbuf[3]=0xca;txbuf[4]=0xde;txbuf[5]=control.node==1?2:1;txbuf[7]=control.node;txbuf[9]='M';txbuf[10]=1;txbuf[11]=type;put(txbuf,12,control.run);put(txbuf,16,seq);put(txbuf,20,attempt);put(txbuf,24,control.aggregation);txlen=30;if(type==2){payload(txbuf+28,seq);txlen+=data_bytes();}}
static uint64_t txstamp(void){uint8_t b[5];dwt_readtxtimestamp(b);uint64_t t=0;for(unsigned i=0;i<5;i++)t|=(uint64_t)b[i]<<(8*i);return t;}
static int transmit(uint64_t scheduled){off();dwt_writetxdata(txlen-2,txbuf,0);dwt_writetxfctrl(txlen,0,0);if(scheduled)dwt_setdelayedtrxtime((uint32_t)(scheduled>>8));int e=dwt_starttx(scheduled?DWT_START_TX_DELAYED:DWT_START_TX_IMMEDIATE);if(e&&scheduled){stats.late_tx++;off();e=dwt_starttx(DWT_START_TX_IMMEDIATE);}if(e){stats.tx_errors++;return 0;}uint32_t t=ticks();while(!(dwt_readsysstatuslo()&DWT_INT_TXFRS_BIT_MASK)){if(ticks()-t>10000){stats.tx_errors++;off();return 0;}}dwt_writesysstatuslo(DWT_INT_TXFRS_BIT_MASK);uint64_t stamp=txstamp();if(txbuf[11]==2){stats.tx_data++;if(have_stamp&&control.mode!=2){uint64_t dt=(stamp-last_stamp)&0xffffffffffULL;uint32_t us=(dt*10+319488)/638976;period_sum+=dt;stats.period_n++;stats.period_lo=period_sum;stats.period_hi=period_sum>>32;if(us<stats.period_min)stats.period_min=us;if(us>stats.period_max)stats.period_max=us;period_hist[us<2047?us:2047]++;}have_stamp=1;}else stats.tx_poll++;last_stamp=stamp;return 1;}
static int receive(void){uint32_t s=dwt_readsysstatuslo();if(s&DWT_INT_RXFCG_BIT_MASK){rxlen=dwt_getframelength(0);if(rxlen>=30&&rxlen<=68)dwt_readrxdata(rxbuf,rxlen,0);uint8_t ts[5];dwt_readrxtimestamp(ts,DWT_IP_M);rxstamp=0;for(unsigned i=0;i<5;i++)rxstamp|=(uint64_t)ts[i]<<(8*i);dwt_writesysstatuslo(DWT_INT_RXFCG_BIT_MASK);if(rxlen<30||rxlen>68||rxbuf[9]!='M'||rxbuf[10]!=1||get(rxbuf,12)!=control.run||get(rxbuf,16)>=control.count||get(rxbuf,24)!=control.aggregation||rxbuf[7]!=(control.node==1?2:1)||rxlen!=(rxbuf[11]==2?30+data_bytes():30)){stats.invalid++;return -1;}if(rxbuf[11]==1)stats.rx_poll++;else if(rxbuf[11]==2)stats.rx_data++;else {stats.invalid++;return -1;}return 1;}if(s&(SYS_STATUS_ALL_RX_ERR|SYS_STATUS_ALL_RX_TO)){stats.phy_errors++;return -1;}return 0;}
static int record(void){uint32_t seq=get(rxbuf,16),attempt=get(rxbuf,20);if(!valid_payload(seq)){stats.invalid++;return 0;}if(drop(seq,attempt,2)){stats.data_dropped++;return 0;}uint8_t bit=1u<<(seq%8);if(received[seq/8]&bit){stats.duplicates++;return 1;}received[seq/8]|=bit;stats.unique++;if(!attempt)stats.first_unique++;return 1;}
static void responder(void){int r=receive();if(!r)return;if(r<0){listen();return;}uint32_t seq=get(rxbuf,16),attempt=get(rxbuf,20);if(control.mode==2&&rxbuf[11]==1){if(drop(seq,attempt,1)){stats.poll_dropped++;listen();return;}uint64_t scheduled=stamp_us(rxstamp,airtime(30)+control.ifs_us);prepare(2,seq,attempt);transmit(scheduled);}else if(control.mode!=2&&rxbuf[11]==2)record();else stats.invalid++;listen();}
static void run(void){uint32_t start=ticks(),batch=300/control.aggregation;uint64_t next=0;for(uint32_t first=0;first<control.count&&control.command!=3;first+=batch){uint32_t bt=ticks(),failed=0,end=first+batch;if(end>control.count)end=control.count;for(uint32_t seq=first;seq<end&&control.command!=3;seq++){if(control.mode==2){int success=0;for(unsigned k=0;k<control.max_attempts&&!success&&control.command!=3;k++){prepare(1,seq,k);if(!transmit(next))continue;listen();uint32_t wait=ticks();while(ticks()-wait<control.timeout_us){int r=receive();if(r==1){if(rxbuf[11]==2&&get(rxbuf,16)==seq&&get(rxbuf,20)==k){next=stamp_us(rxstamp,airtime(30+data_bytes())+control.ifs_us);success=record();break;}stats.invalid++;listen();}else if(r<0)listen();}off();if(!success){stats.timeouts++;next=0;}}if(!success)failed++;}else{unsigned repeats=control.mode==1?5:1;for(unsigned k=0;k<repeats&&control.command!=3;k++){prepare(2,seq,k);transmit(next);next=stamp_us(last_stamp,airtime(30+data_bytes())+control.ifs_us);}}stats.completed++;}unsigned b=stats.batches;if(b<1667){batch_us[b]=ticks()-bt;batch_failed[b]=failed;stats.batches++;}stats.failed+=failed;stats.elapsed=ticks()-start;}off();stats.state=control.command==3?5:3;}
int main(void){
/* PLATFORM_INIT */
while(1){if(control.command){unsigned cmd=control.command;control.command=0;if(cmd==3){if(stats.devid==0xdeca0302)off();stats.state=5;continue;}memset((void*)&stats,0,sizeof(stats));memset(received,0,sizeof(received));memset(batch_us,0,sizeof(batch_us));memset(batch_failed,0,sizeof(batch_failed));memset(period_hist,0,sizeof(period_hist));have_stamp=0;period_sum=0;stats.period_min=0xffffffffu;stats.run=control.run;if(control.count>50000||!control.count||(control.aggregation!=1&&control.aggregation!=10)||control.mode>2){stats.state=90;continue;}int e=setup();if(e){stats.state=100-e;continue;}stats.state=cmd;if(cmd==2)run();else listen();}if(stats.state==1)responder();}}
